CREATE OR REPLACE VIEW `prj-drgfly-prod-sp-01.bq_ds_prod_euw2_oceania_cube_gold_1.dbo_Fact_KPI_Priority_DEPRECATED`
AS
SELECT        LabelNo, CountryCode, Category, RealisedDate, ServiceType, SLA, KPIPickup, KPILEA, KPIDelivery, KPIPickupImpact, KPILEAImpact, KPIDeliveryImpact, DueDate, KPIDepartureDate, KPIArrivalDate, KPIAttemptedDate, 
                         KPIAttemptedDateAdjust, ActualDepartureDate, ActualDepartureRF, ActualDepartureCF, ActualDepartureType, ActualDepartureStatus, ActualFirstArrivalDate, ActualFirstArrivalRF, ActualFirstArrivalCF, ActualFirstArrivalType, 
                         ActualFirstArrivalStatus, ActualArrivalDate, ActualArrivalRF, ActualArrivalCF, ActualArrivalType, ActualArrivalStatus, ActualAttemptedDate, ActualAttemptedRF, ActualAttemptedCF, ActualAttemptedType, ActualAttemptedStatus, 
                         ActualDeliveryScanDate, ActualDeliveryRF, ActualDeliveryCF, ActualDeliveryType, ActualDeliveryStatus, LastScanDate, LastScanRF, LastScanCF, LastScanType, LastScanStatus, MISScanDate, MISRF, LastUpdated, 
                         ProcessID, FromRf, FromCf, ToRf, ToCf, CustomerId, ToLocality, ToPostalCode

FROM            (SELECT        COALESCE (KPI.LabelNo, Interim.LabelNo) AS LabelNo, COALESCE (KPI.CountryCode, Interim.CountryCode) AS CountryCode, COALESCE (KPI.Category, Interim.Category) AS Category, COALESCE (KPI.RealisedDate, 
                                                    Interim.RealisedDate) AS RealisedDate, COALESCE (KPI.ServiceType, Interim.ServiceType) AS ServiceType, COALESCE (KPI.SLA, Interim.SLA) AS SLA, COALESCE (KPI.KPIPickup, Interim.KPIPickup) AS KPIPickup, 
                                                    COALESCE (KPI.KPILEA, Interim.KPILEA) AS KPILEA, COALESCE (KPI.KPIDelivery, Interim.KPIDelivery) AS KPIDelivery, COALESCE (KPI.KPIPickupImpact, Interim.KPIPickupImpact) AS KPIPickupImpact, 
                                                    COALESCE (KPI.KPILEAImpact, Interim.KPILEAImpact) AS KPILEAImpact, COALESCE (KPI.KPIDeliveryImpact, Interim.KPIDeliveryImpact) AS KPIDeliveryImpact, COALESCE (KPI.DueDate, Interim.DueDate) AS DueDate,
                                                     COALESCE (KPI.KPIDepartureDate, Interim.KPIDepartureDate) AS KPIDepartureDate, COALESCE (KPI.KPIArrivalDate, Interim.KPIArrivalDate) AS KPIArrivalDate, COALESCE (KPI.KPIAttemptedDate, 
                                                    Interim.KPIAttemptedDate) AS KPIAttemptedDate, COALESCE (KPI.KPIAttemptedDateAdjust, Interim.KPIAttemptedDateAdjust) AS KPIAttemptedDateAdjust, COALESCE (KPI.ActualDepartureDate, 
                                                    Interim.ActualDepartureDate) AS ActualDepartureDate, COALESCE (KPI.ActualDepartureRF, Interim.ActualDepartureRF) AS ActualDepartureRF, COALESCE (KPI.ActualDepartureCF, Interim.ActualDepartureCF) 
                                                    AS ActualDepartureCF, COALESCE (KPI.ActualDepartureType, Interim.ActualDepartureType) AS ActualDepartureType, COALESCE (KPI.ActualDepartureStatus, Interim.ActualDepartureStatus) AS ActualDepartureStatus, 
                                                    COALESCE (KPI.ActualFirstArrivalDate, Interim.ActualFirstArrivalDate) AS ActualFirstArrivalDate, COALESCE (KPI.ActualFirstArrivalRF, Interim.ActualFirstArrivalRF) AS ActualFirstArrivalRF, 
                                                    COALESCE (KPI.ActualFirstArrivalCF, Interim.ActualFirstArrivalCF) AS ActualFirstArrivalCF, COALESCE (KPI.ActualFirstArrivalType, Interim.ActualFirstArrivalType) AS ActualFirstArrivalType, 
                                                    COALESCE (KPI.ActualFirstArrivalStatus, Interim.ActualFirstArrivalStatus) AS ActualFirstArrivalStatus, COALESCE (KPI.ActualArrivalDate, Interim.ActualArrivalDate) AS ActualArrivalDate, COALESCE (KPI.ActualArrivalRF,
                                                     Interim.ActualArrivalRF) AS ActualArrivalRF, COALESCE (KPI.ActualArrivalCF, Interim.ActualArrivalCF) AS ActualArrivalCF, COALESCE (KPI.ActualArrivalType, Interim.ActualArrivalType) AS ActualArrivalType, 
                                                    COALESCE (KPI.ActualArrivalStatus, Interim.ActualArrivalStatus) AS ActualArrivalStatus, COALESCE (KPI.ActualAttemptedDate, Interim.ActualAttemptedDate) AS ActualAttemptedDate, 
                                                    COALESCE (KPI.ActualAttemptedRF, Interim.ActualAttemptedRF) AS ActualAttemptedRF, COALESCE (KPI.ActualAttemptedCF, Interim.ActualAttemptedCF) AS ActualAttemptedCF, COALESCE (KPI.ActualAttemptedType, 
                                                    Interim.ActualAttemptedType) AS ActualAttemptedType, COALESCE (KPI.ActualAttemptedStatus, Interim.ActualAttemptedStatus) AS ActualAttemptedStatus, COALESCE (KPI.ActualDeliveryScanDate, 
                                                    Interim.ActualDeliveryScanDate) AS ActualDeliveryScanDate, COALESCE (KPI.ActualDeliveryRF, Interim.ActualDeliveryRF) AS ActualDeliveryRF, COALESCE (KPI.ActualDeliveryCF, Interim.ActualDeliveryCF) 
                                                    AS ActualDeliveryCF, COALESCE (KPI.ActualDeliveryType, Interim.ActualDeliveryType) AS ActualDeliveryType, COALESCE (KPI.ActualDeliveryStatus, Interim.ActualDeliveryStatus) AS ActualDeliveryStatus, 
                                                    COALESCE (Interim.LastScanDate, KPI.LastScanDate) AS LastScanDate, COALESCE (Interim.LastScanRF, KPI.LastScanRF) AS LastScanRF, COALESCE (Interim.LastScanCF, KPI.LastScanCF) AS LastScanCF, 
                                                    COALESCE (Interim.LastScanType, KPI.LastScanType) AS LastScanType, COALESCE (Interim.LastScanStatus, KPI.LastScanStatus) AS LastScanStatus, COALESCE (KPI.MISScanDate, Interim.MISScanDate) 
                                                    AS MISScanDate, COALESCE (KPI.MISRF, Interim.MISRF) AS MISRF, COALESCE (Interim.LastUpdated, KPI.LastUpdated) AS LastUpdated, COALESCE (KPI.ProcessID, Interim.ProcessID) AS ProcessID,
                                                    COALESCE(Interim.FromRf, KPI.FromRf) AS FromRf, COALESCE(Interim.FromCf, KPI.FromCf) AS FromCf, COALESCE(Interim.ToRf, KPI.ToRf) AS ToRf, COALESCE(Interim.ToCf, KPI.ToCf) AS ToCf,
                                                    COALESCE(Interim.CustomerId, KPI.CustomerId) AS CustomerId, COALESCE(Interim.ToLocality, KPI.ToLocality) AS ToLocality, COALESCE(Interim.ToPostalCode, KPI.ToPostalCode) AS ToPostalCode    
                                                    FROM            `prj-drgfly-prod-sp-01.bq_ds_prod_euw2_oceania_cube_gold_1.dbo_Fact_KPI_Interim` AS Interim FULL OUTER JOIN
                                                        (SELECT        LabelNo, CountryCode, Category, RealisedDate, ServiceType, SLA, KPIPickup, KPILEA, KPIDelivery, KPIPickupImpact, KPILEAImpact, KPIDeliveryImpact, DueDate, KPIDepartureDate, KPIArrivalDate, 
                                                                                    KPIAttemptedDate, KPIAttemptedDateAdjust, ActualDepartureDate, ActualDepartureRF, ActualDepartureCF, ActualDepartureType, ActualDepartureStatus, ActualFirstArrivalDate, ActualFirstArrivalRF, 
                                                                                    ActualFirstArrivalCF, ActualFirstArrivalType, ActualFirstArrivalStatus, ActualArrivalDate, ActualArrivalRF, ActualArrivalCF, ActualArrivalType, ActualArrivalStatus, ActualAttemptedDate, ActualAttemptedRF, 
                                                                                    ActualAttemptedCF, ActualAttemptedType, ActualAttemptedStatus, ActualDeliveryScanDate, ActualDeliveryRF, ActualDeliveryCF, ActualDeliveryType, ActualDeliveryStatus, LastScanDate, LastScanRF, 
                                                                                    LastScanCF, LastScanType, LastScanStatus, MISScanDate, MISRF, LastUpdated, ProcessID,FromRf, FromCf, ToRf, ToCf, CustomerId, ToLocality, ToPostalCode
                                                          FROM            `prj-drgfly-prod-sp-01.bq_ds_prod_euw2_oceania_cube_gold_1.dbo_Fact_KPI_Daily_Priority`) AS KPI ON KPI.LabelNo = Interim.LabelNo) AS A
 WHERE ServiceType = 'P'